static void generateDependenciesBlock(Map<String,String> jarToCoords) {
    StringBuilder pom = new StringBuilder(), gradle = new StringBuilder();
    for (String coords : jarToCoords.values()) {
        String[] p = coords.split(":");
        pom.append("<dependency><groupId>").append(p[0]).append("</groupId><artifactId>").append(p[1]).append("</artifactId><version>").append(p[2]).append("</version></dependency>\n");
        gradle.append("implementation '").append(coords).append("'\n");
    }
    System.out.println(pom); System.out.println(gradle);
}
generateDependenciesBlock(Map.of("commons-io.jar","commons-io:commons-io:2.16.1", "log4j.jar","log4j:log4j:1.2.17"));

