static String translateMavenDependencyToGradle(String g, String a, String v, String scope) {
    String config = switch (scope) {
        case "compile" -> "implementation";
        case "provided" -> "compileOnly";
        case "runtime" -> "runtimeOnly";
        case "test" -> "testImplementation";
        default -> "implementation";
    };
    return config + " '" + g + ":" + a + ":" + v + "'";
}
System.out.println(translateMavenDependencyToGradle("com.google.code.gson","gson","2.11.0","compile"));

