static String isFeasibleToMigrateToMaven(int customTasks, boolean usesCache, int subprojects) {
    if (customTasks > 3) return "NIE - zbyt wiele custom taskow (" + customTasks + ")";
    if (usesCache) return "OSTROZNIE - utrata build cache wydluzy buildy";
    return "TAK - prosty projekt, migracja realistyczna";
}
