static void migrateAntToMaven(String xml) {
    Map<String,String> mapping = Map.of("clean","faza clean","compile","faza compile","test","maven-surefire-plugin","jar","faza package + maven-jar-plugin");
    Matcher m = Pattern.compile("<target name=\"(\\w+)\"").matcher(xml);
    while (m.find()) {
        String target = m.group(1);
        System.out.println(target + " -> " + mapping.getOrDefault(target, "brak wprost odpowiednika, sprawdz plugin"));
    }
}

static String migrateAntToGradle(String xml) {
    StringBuilder sb = new StringBuilder();
    Matcher m = Pattern.compile("<target name=\"(\\w+)\"").matcher(xml);
    while (m.find()) sb.append("tasks.register('").append(m.group(1)).append("') { doLast { /* TODO: przenies logike z Ant targetu */ } }\n");
    return sb.toString();
}

static void detectMismatches(List<String> antLibs, List<String> mavenDeps, List<String> gradleDeps) {
    Set<String> all = new HashSet<>();
    all.addAll(antLibs); all.addAll(mavenDeps); all.addAll(gradleDeps);
    for (String dep : all) {
        boolean inAll = antLibs.contains(dep) && mavenDeps.contains(dep) && gradleDeps.contains(dep);
        if (!inAll) System.out.println("NIEZGODNOSC: " + dep + " brakuje w co najmniej jednym pliku");
    }
}

static String scoreMigrationRisk(int custom, int nonStandard, int missingLib) {
    int score = custom * 3 + nonStandard * 2 + missingLib * 4;
    String level = score < 10 ? "NISKIE" : (score < 25 ? "SREDNIE" : "WYSOKIE");
    return "Wynik: " + score + " (" + level + ")";
}
System.out.println(scoreMigrationRisk(1,0,0));
System.out.println(scoreMigrationRisk(5,3,4));

static Map<String,String> antToMaven = Map.of("clean","clean","compile","compile","jar","package");
static Map<String,String> mavenToGradle = Map.of("clean","clean","compile","compileJava","package","jar");
static String chainMapping(String antTarget) {
    String phase = antToMaven.get(antTarget);
    return mavenToGradle.get(phase);
}
System.out.println(chainMapping("jar"));

static String classifyCustomLogicComplexity(String xml) {
    if (xml.contains("<script>") || xml.contains("<macrodef>")) return "TRUDNA - wymaga wlasnego pluginu lub pelnego przepisania";
    if (xml.contains("<exec>")) return "SREDNIA - mozna wywolac zewnetrzny proces z Gradle/Maven";
    return "PROSTA - standardowe taski maja gotowy odpowiednik";
}
System.out.println(classifyCustomLogicComplexity("<target><script>...</script></target>"));

static void verifyEquivalence(String buildXml, String pomXml, String buildGradle, String expectedMainClass) {
    boolean ok = buildXml.contains(expectedMainClass) && pomXml.contains(expectedMainClass) && buildGradle.contains(expectedMainClass);
    System.out.println("Main-Class spojna we wszystkich 3 plikach: " + ok);
}

static double estimateMigrationHours(int targets, int custom, int deps, boolean nonStandard) {
    double hours = targets * 0.5 + custom * 4 + deps * 0.25;
    if (nonStandard) hours += 8;
    return hours;
}
System.out.println(estimateMigrationHours(5, 1, 10, false) + "h");
System.out.println(estimateMigrationHours(20, 5, 40, true) + "h");

